def _family(name):
    return name.split("_", 1)[0] if "_" in name else "kb"


def scan(root=None):
    root = root or K.VAULT
    paths = glob.glob(os.path.join(root, "tools", "*.py"))
    paths += glob.glob(os.path.join(root, "projects", "*", "ingest", "tools", "*.py"))
    rows = []
    for path in sorted(paths):
        rel = os.path.relpath(path, root).replace("\\", "/")
        name = os.path.basename(path)
